package com.onlinequiz.repository;

import java.sql.Connection;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;

/**
 * Small JDBC helpers shared by the repositories.
 */
final class JdbcSupport {

    private JdbcSupport() {
    }

    /**
     * Reads the id generated by the most recent INSERT on this connection.
     * SQLite exposes it through the {@code last_insert_rowid()} function.
     */
    static int lastInsertId(Connection connection) throws SQLException {
        try (Statement statement = connection.createStatement();
             ResultSet resultSet = statement.executeQuery("SELECT last_insert_rowid()")) {
            return resultSet.next() ? resultSet.getInt(1) : 0;
        }
    }

    static void requireSingleRow(int affectedRows, String operation) throws SQLException {
        if (affectedRows != 1) {
            throw new SQLException(operation + " affected " + affectedRows + " rows instead of 1");
        }
    }
}
